#include <iostream>
#include <string>
#include <map>
#include <functional>
#include <future>
#include <mutex>
#include <chrono>
#include <random>
#include <sstream>
#include <vector>
#include <memory>
#include <algorithm>
#include <iomanip>

namespace cicd {

class TokenStore {
public:
    static TokenStore& instance() {
        static TokenStore store;
        return store;
    }

    std::string generate_session_token(const std::string& user_id) {
        std::lock_guard<std::mutex> lock(mtx_);
        std::string token = make_random_token();
        sessions_[token] = user_id;
        return token;
    }

    std::string generate_csrf_token(const std::string& session_token) {
        std::lock_guard<std::mutex> lock(mtx_);
        std::string csrf = make_random_token();
        csrf_tokens_[session_token] = csrf;
        return csrf;
    }

    bool validate_session(const std::string& token) {
        std::lock_guard<std::mutex> lock(mtx_);
        return sessions_.find(token) != sessions_.end();
    }

    bool validate_csrf(const std::string& session_token, const std::string& csrf_token) {
        std::lock_guard<std::mutex> lock(mtx_);
        auto it = csrf_tokens_.find(session_token);
        if (it == csrf_tokens_.end()) return false;
        return it->second == csrf_token;
    }

private:
    std::string make_random_token() {
        // Use a cryptographically secure random source directly.
        // std::random_device provides non-deterministic randomness on
        // supported platforms; draw enough entropy (256 bits) for tokens.
        std::random_device rd;
        std::ostringstream oss;
        oss << std::hex << std::setfill('0');
        for (int i = 0; i < 8; ++i) {
            oss << std::setw(8) << rd();
        }
        return oss.str();
    }

    std::mutex mtx_;
    std::map<std::string, std::string> sessions_;
    std::map<std::string, std::string> csrf_tokens_;
};

struct PipelineRequest {
    std::string session_token;
    std::string csrf_token;
    std::string action;  // "trigger_build", "deploy", "rollback"
    std::string target_repo;
    std::string branch;
    std::string origin_header;
};

struct ValidationResult {
    bool session_valid;
    bool csrf_valid;
    bool origin_valid;
    std::string error;
};

class PipelineController {
public:
    PipelineController() : allowed_origins_({"https://ci.internal.corp", "https://admin.internal.corp"}) {}

    std::future<ValidationResult> validate_request_async(const PipelineRequest& req) {
        return std::async(std::launch::async, [this, req]() {
            return perform_validation(req);
        });
    }

    std::future<bool> execute_pipeline_async(const PipelineRequest& req) {
        return std::async(std::launch::async, [this, req]() {
            auto validation_future = validate_request_async(req);
            auto result = validation_future.get();

            if (!check_authorization(result, req)) {
                std::cerr << "Authorization failed: " << result.error << std::endl;
                return false;
            }

            return dispatch_action(req);
        });
    }

private:
    ValidationResult perform_validation(const PipelineRequest& req) {
        ValidationResult result;
        result.session_valid = TokenStore::instance().validate_session(req.session_token);
        result.csrf_valid = TokenStore::instance().validate_csrf(req.session_token, req.csrf_token);
        result.origin_valid = check_origin(req.origin_header);

        if (!result.session_valid) result.error = "invalid_session";
        else if (!result.csrf_valid) result.error = "csrf_mismatch";
        else if (!result.origin_valid) result.error = "origin_rejected";
        else result.error = "";

        return result;
    }

    bool check_origin(const std::string& origin) {
        if (origin.empty()) return false;  // Reject requests without Origin header
        return std::find(allowed_origins_.begin(), allowed_origins_.end(), origin) != allowed_origins_.end();
    }

    bool check_authorization(const ValidationResult& result, const PipelineRequest& req) {
        // For state-changing operations, require full validation
        if (req.action == "trigger_build" || req.action == "deploy" || req.action == "rollback") {
            // Session must be valid AND csrf must be valid AND origin must be valid
            // Defense-in-depth: ALL checks must pass for state-changing operations
            return result.session_valid && result.csrf_valid && result.origin_valid;
        }
        return result.session_valid;
    }

    bool dispatch_action(const PipelineRequest& req) {
        std::cout << "[PIPELINE] Executing " << req.action << " on "
                  << req.target_repo << ":" << req.branch << std::endl;
        // Actual CI/CD dispatch logic
        return true;
    }

    std::vector<std::string> allowed_origins_;
};

}  // namespace cicd

int main() {
    using namespace cicd;

    // Simulate: user authenticates and gets tokens
    auto session = TokenStore::instance().generate_session_token("engineer_alice");
    auto csrf = TokenStore::instance().generate_csrf_token(session);

    // Legitimate request
    PipelineRequest legit_req;
    legit_req.session_token = session;
    legit_req.csrf_token = csrf;
    legit_req.action = "deploy";
    legit_req.target_repo = "backend-service";
    legit_req.branch = "main";
    legit_req.origin_header = "https://ci.internal.corp";

    PipelineController controller;
    auto future = controller.execute_pipeline_async(legit_req);
    bool success = future.get();
    std::cout << "Legitimate request result: " << (success ? "OK" : "DENIED") << std::endl;

    // Cross-origin attack request (no CSRF token, spoofed via form submission)
    PipelineRequest attack_req;
    attack_req.session_token = session;  // Cookie sent automatically
    attack_req.csrf_token = "invalid_token";
    attack_req.action = "deploy";
    attack_req.target_repo = "backend-service";
    attack_req.branch = "attacker-branch";
    attack_req.origin_header = "";  // Attacker strips Origin header

    auto attack_future = controller.execute_pipeline_async(attack_req);
    bool attack_success = attack_future.get();
    std::cout << "Attack request result: " << (attack_success ? "OK" : "DENIED") << std::endl;

    return 0;
}
